    "population": "1,506 adults with atrial fibrillation requiring oral anticoagulation and a successful PCI for stable coronary disease or acute coronary syndrome (edoxaban regimen 751; vitamin K antagonist regimen 755). Randomization was 4 hours to 5 days after PCI. Median age 70 years (interquartile range 63–77). 26% women. Acute coronary syndrome was the PCI indication in 777 of 1,506 (52%). Median CHA2DS2-VASc 4. 186 sites in 18 countries.",
    "intervention": "Edoxaban 60 mg once daily plus a P2Y12 inhibitor for 12 months. The paper reduced edoxaban to 30 mg once daily if creatinine clearance was 15–50 mL/min, body weight was 60 kg or less, or a specified potent P-glycoprotein inhibitor was in use. 147 of 746 patients (20%) assigned to edoxaban started at 30 mg. Clopidogrel 75 mg daily was the usual P2Y12 inhibitor (1,391 of 1,506, 92%). Prasugrel or ticagrelor was allowed.",
    "comparator": "A vitamin K antagonist (INR 2.0–3.0) plus a P2Y12 inhibitor for 12 months and aspirin 100 mg once daily for 1 to 12 months, with the aspirin duration chosen before randomization. Median duration of triple therapy was 66 days (interquartile range 33–188). Median time in therapeutic range was 63.1% (interquartile range 46.3–75.6).",
    "primaryResult": "Intention-to-treat ISTH major or clinically relevant nonmajor bleeding at 12 months: 128 of 751 (17%; annualized 20.7%) with edoxaban versus 152 of 755 (20%; annualized 25.6%) with the vitamin K antagonist regimen (HR 0.83; 95% CI 0.65–1.05; P=0.0010 for noninferiority, margin HR 1.20; P=0.1154 for superiority). Noninferior, not superior. The paper says the bleeding difference was mainly clinically relevant nonmajor bleeding.",
    "safety": "Main efficacy composite (cardiovascular death, stroke, systemic embolism, myocardial infarction, or definite stent thrombosis): 49 of 751 (7%; annualized 7.3%) versus 46 of 755 (6%; annualized 6.9%) (HR 1.06; 95% CI 0.71–1.69). No formal hypothesis test was planned for that composite. The paper says the trial was underpowered for small ischemic differences and notes a very early numerical increase in myocardial infarction, stent thrombosis, and cardiovascular death without aspirin. That note is a discussion point, not a significant primary result.",
    "takeaway": "After PCI in atrial fibrillation, the edoxaban plus P2Y12 regimen the trial used was noninferior, and not superior, to vitamin K antagonist triple therapy for major or clinically relevant nonmajor bleeding. Ischemic event rates were similar and imprecise.",
