    "designNotes": "Randomized, open-label phase 3b noninferiority trial with masked outcome adjudication (ClinicalTrials.gov NCT02866175). Primary analysis was intention-to-treat for ISTH major or clinically relevant nonmajor bleeding at 12 months. The noninferiority margin was a hazard ratio of 1.20. Aspirin duration on the vitamin K antagonist arm was investigator-chosen, from 1 to 12 months, and declared before randomization.",
    "strengths": "Randomized comparison with blinded adjudication, a prespecified noninferiority margin, and a separate main ischemic composite so the bleeding result is not taught as fewer heart attacks or strokes.",
