    "journalClub": "Noninferior bleeding. Randomized, adjudicated, margin 1.20. Limited because superiority was not shown and the ischemic composite was not powered. ENTRUST-AF PCI is read as the edoxaban member of the AF–PCI set, beside PIONEER AF-PCI, RE-DUAL PCI, and AUGUSTUS.",
