    "population": "Two cohorts in one trial. Registry NCT02247128 names cohort A as patients without an indication for oral anticoagulation before TAVI, and cohort B as patients with one. Cohort A, no long-term oral-anticoagulation indication: aspirin alone 331, aspirin plus clopidogrel 334. The Brouwer abstract does not print age or sex. During the trial, 44 patients (13.3%) assigned to aspirin alone and 32 (9.6%) assigned to aspirin plus clopidogrel received oral anticoagulation. Cohort B, already on oral anticoagulation: oral anticoagulation alone 157, oral anticoagulation plus clopidogrel 156. The Nijenhuis abstract does not say what fraction was a DOAC versus a vitamin K antagonist.",
    "intervention": "Cohort A: aspirin alone. The Brouwer abstract does not print the aspirin milligram dose. Cohort B: oral anticoagulation alone. Clopidogrel was not added.",
    "comparator": "Cohort A: aspirin plus clopidogrel for 3 months. The Brouwer abstract does not print the clopidogrel milligram dose. Cohort B: oral anticoagulation plus clopidogrel for 3 months.",
    "primaryResult": "Cohort A, no long-term oral-anticoagulation indication (Brouwer et al.). Two primary bleeding outcomes over 12 months. All bleeding: 50 of 331 (15.1%) with aspirin alone versus 89 of 334 (26.6%) with aspirin plus clopidogrel (risk ratio 0.57; 95% CI 0.42–0.77; P=0.001). Non-procedure-related bleeding: 50 (15.1%) versus 83 (24.9%) (risk ratio 0.61; 95% CI 0.44–0.83; P=0.005). Most bleeding at the TAVI puncture site counted as non-procedure-related. Cohort B, already on oral anticoagulation (Nijenhuis et al.). Two primary outcomes over 12 months. All bleeding: 34 of 157 (21.7%) with oral anticoagulation alone versus 54 of 156 (34.6%) with oral anticoagulation plus clopidogrel (risk ratio 0.63; 95% CI 0.43–0.90; P=0.01). Non-procedure-related bleeding: 34 (21.7%) versus 53 (34.0%) (risk ratio 0.64; 95% CI 0.44–0.92; P=0.02). Procedure-related bleeding was defined as BARC type 4 severe bleeding, so most access-site bleeding counted as non-procedure-related. The rates are not pooled.",
    "safety": "Cohort A secondary composite 1 (cardiovascular death, non-procedure-related bleeding, stroke, or myocardial infarction): 76 (23.0%) versus 104 (31.1%) (difference −8.2 percentage points; 95% CI for noninferiority −14.9 to −1.5; risk ratio 0.74; 95% CI for superiority 0.57–0.95; P=0.04). That composite includes bleeding. Cohort A secondary composite 2 (cardiovascular death, ischemic stroke, or myocardial infarction): 32 (9.7%) versus 33 (9.9%) (difference −0.2 percentage points; 95% CI for noninferiority −4.7 to 4.3; P=0.004 for noninferiority; risk ratio 0.98; 95% CI for superiority 0.62–1.55; P=0.93). Cohort B: most bleeding was in the first month, was minor, and was at the TAVI access site. Cohort B secondary composite 1 (cardiovascular death, non-procedure-related bleeding, stroke, or myocardial infarction): 49 (31.2%) versus 71 (45.5%) (difference −14.3 percentage points; 95% CI for noninferiority −25.0 to −3.6; risk ratio 0.69; 95% CI for superiority 0.51–0.92). Cohort B secondary composite 2 (cardiovascular death, ischemic stroke, or myocardial infarction): 21 (13.4%) versus 27 (17.3%) (difference −3.9 percentage points; 95% CI for noninferiority −11.9 to 4.0; risk ratio 0.77; 95% CI for superiority 0.46–1.31). The noninferiority margin for the secondary composites in both papers was 7.5 percentage points. Less bleeding is not fewer ischemic events.",
    "takeaway": "Two cohorts. Cohort A, no long-term oral-anticoagulation indication: aspirin alone had less 12-month bleeding than aspirin plus clopidogrel (15.1% vs 26.6%). Cohort B, already on oral anticoagulation: anticoagulation alone had less 12-month bleeding than anticoagulation plus clopidogrel (21.7% vs 34.6%).",
    "cite": "Cohort A, no long-term oral-anticoagulation indication: Brouwer J, et al. N Engl J Med. 2020;383:1447-1457. https://doi.org/10.1056/NEJMoa2017815. Cohort B, already on oral anticoagulation: Nijenhuis VJ, et al. N Engl J Med. 2020;382:1696-1707. https://doi.org/10.1056/NEJMoa1915152.",
