    "caveats": "Bleeding primaries: 21.7% vs 34.6% for all bleeding (risk ratio 0.63; 95% CI 0.43–0.90). Most bleeding was minor access-site bleeding. The rates here are from the oral anticoagulation cohort, not the aspirin cohort. This trial is distinct from ENVISAGE-TAVI AF.",
    "practiceTakeaway": "In the POPular TAVI cohort already on oral anticoagulation, anticoagulation alone had less 12-month bleeding than anticoagulation plus clopidogrel for 3 months (21.7% vs 34.6%; risk ratio 0.63; 95% CI 0.43–0.90).",
