    "designNotes": "Randomized. Phase 2 dose-validation study, stopped early. Primary end point: dabigatran trough level. Clinical events were the reason for stopping and are not a completed efficacy comparison. ClinicalTrials.gov NCT01452347 and NCT01505881, as listed in the paper. The abstract gives the clinical counts as percentages of the dabigatran and warfarin groups in the as-treated analysis.",
